#include <bits/stdc++.h>
using namespace std;

int gcdTwo(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int findGcd(vector<int>& arr) {
    if (arr.empty()) return 0;
    int result = arr[0];
    for (int i = 1; i < arr.size(); ++i) {
        result = gcdTwo(result, arr[i]);
        if (result == 1) break;
    }
    return result;
}

// 示例
